BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL TIME ZONE 'UTC';
SET LOCAL search_path='';
SET LOCAL row_security=off;
SET LOCAL statement_timeout='30s';
SET LOCAL lock_timeout='5s';
SET LOCAL idle_in_transaction_session_timeout='30s';
-- Exact synthetic source composition, not an attestation of hosted schema or data.
WITH ns AS (SELECT oid,nspname FROM pg_namespace WHERE nspname IN ('public','private','auth','storage')),
rels AS (SELECT c.*,n.nspname FROM pg_class c JOIN ns n ON n.oid=c.relnamespace WHERE c.relkind IN ('r','p','v','m','S','f') AND c.relname<>'catalogue_fixture_identity_v1'),
parts AS (
 SELECT 'schemas' AS part,coalesce(jsonb_agg(jsonb_build_object('name',nspname,'owner',pg_get_userbyid(nspowner),'acl',nspacl::text) ORDER BY nspname),'[]') AS data FROM pg_namespace WHERE oid IN (SELECT oid FROM ns)
 UNION ALL SELECT 'relations',coalesce(jsonb_agg(jsonb_build_object('name',nspname||'.'||relname,'kind',relkind,'owner',pg_get_userbyid(relowner),'rls',relrowsecurity,'force_rls',relforcerowsecurity,'acl',relacl::text,'persistence',relpersistence,'options',reloptions,'replica_identity',relreplident) ORDER BY nspname,relname),'[]') FROM rels
 UNION ALL SELECT 'columns',coalesce(jsonb_agg(jsonb_build_object('relation',r.nspname||'.'||r.relname,'position',a.attnum,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'identity',a.attidentity,'generated',a.attgenerated,'acl',a.attacl::text) ORDER BY r.nspname,r.relname,a.attnum),'[]') FROM rels r JOIN pg_attribute a ON a.attrelid=r.oid AND a.attnum>0 AND NOT a.attisdropped LEFT JOIN pg_attrdef d ON d.adrelid=r.oid AND d.adnum=a.attnum
 UNION ALL SELECT 'foreign_keys',coalesce(jsonb_agg(jsonb_build_object('relation',r.nspname||'.'||r.relname,'name',c.conname,'target',c.confrelid::regclass::text,'columns',(SELECT jsonb_agg(a.attname ORDER BY k.i) FROM unnest(c.conkey) WITH ORDINALITY k(attnum,i) JOIN pg_attribute a ON a.attrelid=c.conrelid AND a.attnum=k.attnum),'target_columns',(SELECT jsonb_agg(a.attname ORDER BY k.i) FROM unnest(c.confkey) WITH ORDINALITY k(attnum,i) JOIN pg_attribute a ON a.attrelid=c.confrelid AND a.attnum=k.attnum),'update_action',c.confupdtype,'delete_action',c.confdeltype,'match',c.confmatchtype,'validated',c.convalidated,'deferrable',c.condeferrable,'deferred',c.condeferred,'definition',pg_get_constraintdef(c.oid,true)) ORDER BY r.nspname,r.relname,c.conname),'[]') FROM pg_constraint c JOIN rels r ON r.oid=c.conrelid WHERE c.contype='f'
 UNION ALL SELECT 'constraints',coalesce(jsonb_agg(jsonb_build_object('relation',r.nspname||'.'||r.relname,'name',c.conname,'type',c.contype,'validated',c.convalidated,'deferrable',c.condeferrable,'deferred',c.condeferred,'definition',pg_get_constraintdef(c.oid,true)) ORDER BY r.nspname,r.relname,c.conname),'[]') FROM pg_constraint c JOIN rels r ON r.oid=c.conrelid
 UNION ALL SELECT 'functions',coalesce(jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'identity_arguments',pg_get_function_identity_arguments(p.oid),'definition_sha256',encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex'),'prosrc_sha256',encode(sha256(convert_to(p.prosrc,'UTF8')),'hex'),'owner',pg_get_userbyid(p.proowner),'language',l.lanname,'kind',p.prokind,'definer',p.prosecdef,'leakproof',p.proleakproof,'strict',p.proisstrict,'volatility',p.provolatile,'parallel',p.proparallel,'result',pg_get_function_result(p.oid),'config',p.proconfig,'acl',p.proacl::text,'effective_execute',(SELECT jsonb_object_agg(rolname,has_function_privilege(rolname,p.oid,'EXECUTE') ORDER BY rolname) FROM pg_roles WHERE rolname IN ('anon','authenticated','service_role'))) ORDER BY n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)),'[]') FROM pg_proc p JOIN ns n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang WHERE p.prokind IN ('f','p')
 UNION ALL SELECT 'triggers',coalesce(jsonb_agg(jsonb_build_object('relation',r.nspname||'.'||r.relname,'name',CASE WHEN t.tgisinternal THEN '<internal>' ELSE t.tgname END,'function',t.tgfoid::regprocedure::text,'definition',CASE WHEN t.tgisinternal THEN replace(pg_get_triggerdef(t.oid,true),quote_ident(t.tgname),'<internal>') ELSE pg_get_triggerdef(t.oid,true) END,'type',t.tgtype,'enabled',t.tgenabled,'internal',t.tgisinternal,'deferrable',t.tgdeferrable,'deferred',t.tginitdeferred,'constraint',c.conname) ORDER BY r.nspname,r.relname,c.conname,t.tgtype,t.tgname),'[]') FROM pg_trigger t JOIN rels r ON r.oid=t.tgrelid LEFT JOIN pg_constraint c ON c.oid=t.tgconstraint
 UNION ALL SELECT 'policies',coalesce(jsonb_agg(jsonb_build_object('relation',r.nspname||'.'||r.relname,'name',p.polname,'command',p.polcmd,'permissive',p.polpermissive,'roles',(SELECT jsonb_agg(CASE WHEN oid=0 THEN 'PUBLIC' ELSE pg_get_userbyid(oid) END ORDER BY oid) FROM unnest(p.polroles) oid),'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid)) ORDER BY r.nspname,r.relname,p.polname),'[]') FROM pg_policy p JOIN rels r ON r.oid=p.polrelid
 UNION ALL SELECT 'indexes',coalesce(jsonb_agg(jsonb_build_object('relation',r.nspname||'.'||r.relname,'name',c.relname,'definition',pg_get_indexdef(i.indexrelid),'valid',i.indisvalid,'ready',i.indisready,'unique',i.indisunique,'primary',i.indisprimary) ORDER BY r.nspname,r.relname,c.relname),'[]') FROM pg_index i JOIN rels r ON r.oid=i.indrelid JOIN pg_class c ON c.oid=i.indexrelid
 UNION ALL SELECT 'types',coalesce(jsonb_agg(jsonb_build_object('name',n.nspname||'.'||t.typname,'kind',t.typtype,'owner',pg_get_userbyid(t.typowner),'acl',t.typacl::text,'enum',(SELECT jsonb_agg(e.enumlabel ORDER BY e.enumsortorder) FROM pg_enum e WHERE e.enumtypid=t.oid)) ORDER BY n.nspname,t.typname),'[]') FROM pg_type t JOIN ns n ON n.oid=t.typnamespace WHERE t.typtype IN ('e','d')
 UNION ALL SELECT 'roles',coalesce(jsonb_agg(jsonb_build_object('name',rolname,'superuser',rolsuper,'inherit',rolinherit,'create_role',rolcreaterole,'create_db',rolcreatedb,'login',rolcanlogin,'replication',rolreplication,'bypass_rls',rolbypassrls,'config',rolconfig) ORDER BY rolname),'[]') FROM pg_roles WHERE rolname IN ('postgres','anon','authenticated','service_role')
 UNION ALL SELECT 'memberships',coalesce(jsonb_agg(jsonb_build_object('role',pg_get_userbyid(roleid),'member',pg_get_userbyid(member),'grantor',pg_get_userbyid(grantor),'admin',admin_option,'inherit',inherit_option,'set',set_option) ORDER BY roleid::regrole::text,member::regrole::text),'[]') FROM pg_auth_members
 UNION ALL SELECT 'default_acl',coalesce(jsonb_agg(jsonb_build_object('owner',pg_get_userbyid(defaclrole),'schema',(SELECT nspname FROM pg_namespace WHERE oid=defaclnamespace),'type',defaclobjtype,'acl',defaclacl::text) ORDER BY defaclrole::regrole::text,defaclnamespace,defaclobjtype),'[]') FROM pg_default_acl
 UNION ALL SELECT 'rules',coalesce(jsonb_agg(jsonb_build_object('relation',r.nspname||'.'||r.relname,'name',w.rulename,'enabled',w.ev_enabled,'definition',pg_get_ruledef(w.oid,true)) ORDER BY r.nspname,r.relname,w.rulename),'[]') FROM pg_rewrite w JOIN rels r ON r.oid=w.ev_class
 UNION ALL SELECT 'event_triggers',coalesce(jsonb_agg(jsonb_build_object('name',evtname,'event',evtevent,'owner',pg_get_userbyid(evtowner),'function',evtfoid::regprocedure::text,'enabled',evtenabled,'tags',evttags) ORDER BY evtname),'[]') FROM pg_event_trigger
)
SELECT jsonb_object_agg(part,data ORDER BY part) FROM parts;
ROLLBACK;
